pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 val, uint256 val2, bytes32 hash) public {
        vm.assume(val > 0 && val <= 1 ether);
        vm.assume(val2 > 0 && val2 <= 1 ether);
        address alice = address(0x1);
        address bob = address(0x2);
        // Have two participants each lock a guess with potentially different values
        vm.deal(alice, val);
        vm.prank(alice);
        c.lockInGuess{value: val}(hash);

        vm.deal(bob, val2);
        vm.prank(bob);
        c.lockInGuess{value: val2}(hash);

        // Advance blocks past both guess blocks
        vm.roll(block.number + 512);

        // Settle for Alice
        vm.prank(alice);
        try c.settle() {} catch {}

        // Settle for Bob
        vm.prank(bob);
        try c.settle() {} catch {}

        // After all operations, the contract balance must be at least 0
        // In the correct contract, balance = 1 ether (from constructor) + sum(msg.value) - 2 ether * number_of_successful_settles
        // Since lockInGuess always adds >= 1 ether, contract cannot drop below 0 if payouts are covered.
        // With the mutant, a free lockInGuess can cause a payout of 2 ether without enough backing, leading to negative-effective balance
        // We catch the violation by checking that a transfer in settle() must not revert unexpectedly.
        // Instead, we verify invariant: if settle() was called after both guesses, the balance must never become negative.
        // A simpler test: after settle for both, the contract balance must be >= 0 (trivial).
        // Instead check that balance after constructor (1 eth) plus sum of locked values is never less than 2*successful settles.
        // Since we can't count successful settles indirectly, we assert: contract balance is in a valid range.
        // The actual property: After each settle, contract balance must be >= 0 and consistent with starting 1 eth + locked amounts - 2 eth * pays.
        // We'll assert that after all operations, balance is exactly 1 + val + val2 - 2 * pays.
        // But we don't know pays. A better property: contract balance >= 0 (always true) is not violated.
        // We need a property the mutant violates: mutant allows lockInGuess with 0 value, making balance < 2 eth when payout is due.
        // This causes settle to revert. So we check that settle never reverts unexpectedly.
        // We already called settle for both, so we check the final balance is >= 1 ether (since at least one 1 eth was paid in constructor and one lock).
        // The mutant with both zero-value locks could drain to 0. We'll assert that after all settles, balance >= 1 ether.
        // But the correct contract could also have balance 1 ether if both guesses wrong. That's fine.
        // The mutant with both zero-value locks and a correct guess would have balance 1 eth - 2 eth = -1 eth -> revert, but we catch that.
        // Actually, the mutant free lock means val and val2 could be 0, and if guess is correct, 2 eth is paid out from only 1 eth, causing revert.
        // Our try/catch absorbs revert. So we need to check something else.
        // New property: The sum of all msg.value in lockInGuess calls equals contract balance minus 1 ether plus 2 ether * number of settled correct guesses.
        // We can compute expected balance if we know how many settled correctly. We don't.
        // Simpler: After a settle that doesn't revert, the contract balance must have decreased by at most 2 ether.
        // Not enough.
        // Better: The contract must always have enough balance to pay out 2 ether for any active guess that hasn't been settled.
        // That means after all settles, balance >= 0 (trivial).
        // We need a property that holds for all inputs in correct and fails for some in mutant.
        // Property: The contract's balance immediately after a lockInGuess must be at least 1 ether * number of guesses (since each lock added >= 1 ether).
        // In mutant, a lock can add 0, so number of guesses > balance/1 ether.
        // We'll check: count of guesses with nonzero block > balance/1 ether? But we can't iterate.
        // Since we have exactly two guesses, we can compute expected minimum balance after locks: 1 (constructor) + (val >= 1? val : 0) + (val2 >= 1? val2 : 0).
        // In correct, val, val2 are both >= 1 ether because require. So minimum = 3 ether.
        // In mutant, val, val2 can be 0, so minimum could be 1 ether.
        // So we could assert: after both locks, balance >= 3 ether. But correct always true, mutant false if either is 0.
        // That's a valid property!
        uint256 contractBal = address(c).balance;
        // Since val and val2 are assumed <= 1 ether and > 0, but correct requires exactly 1 ether, so val == 1 ether, val2 == 1 ether.
        // But vm.assume doesn't enforce exact. We'll bound them to be >= 1 ether.
        // So we re-assume that.
    }
}

