pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }
    function testFuzz_property(address[] memory actors, bytes32[] memory hashes, uint256[] memory values) public {
        uint256 n = actors.length;
        vm.assume(n > 0 && n == hashes.length && n == values.length);
        // Keep the fuzzed domain wide; only restrict to non-zero addresses for callers.
        for (uint256 i = 0; i < n; i++) {
            vm.assume(actors[i] != address(0));
        }
        uint256 submitted = 0;
        for (uint256 i = 0; i < n; i++) {
            vm.assume(values[i] <= 100 ether);
            vm.deal(actors[i], values[i]);
            vm.prank(actors[i]);
            c.lockInGuess{value: values[i]}(hashes[i]);
            if (values[i] >= 1 ether) {
                // In the reference, only 1-ether calls succeed; in the mutant zeros also succeed.
                // Count submissions that entered in the REFERENCE contract.
                submitted++;
            }
        }
        // general rule: the contract balance must be at least (submitted + 1) * 1 ether,
        // because each accepted guess contributed 1 ether and the constructor holds 1 ether.
        // The mutant allows free locks, reducing the balance below this threshold.
        uint256 minBalance = (submitted + 1) * 1 ether;
        assertTrue(address(c).balance >= minBalance);
    }
}

