contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 firstHash, bytes32 secondHash, address sender) public {
        vm.assume(sender != address(0) && sender != address(c));
        vm.assume(firstHash != bytes32(0) && secondHash != bytes32(0));
        vm.assume(firstHash != secondHash);
        vm.deal(sender, 3 ether);

        vm.prank(sender);
        c.lockInGuess{value: 1 ether}(firstHash);

        // second lock-in call; revert is expected on reference, success on mutant
        bool secondCallOk;
        vm.prank(sender);
        try c.lockInGuess{value: 1 ether}(secondHash) { secondCallOk = true; } catch { secondCallOk = false; }

        bytes32 storedGuessAfter = c.guesses(sender);
        // If second call succeeded (buggy case), stored guess must equal firstHash, but mutant stores secondHash.
        // If second call reverted (reference), stored guess remains firstHash.
        // The invariant is: if second call succeeded, storedGuessAfter == firstHash.
        // Reference always makes secondCallOk false, so implication holds vacuously.
        // Mutant makes secondCallOk true and storedGuessAfter != firstHash, breaking the implication.
        assertTrue(!secondCallOk || storedGuessAfter == firstHash);
    }
}

