pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        // Provide the required 1 ether constructor payment
        c = new C{value: 1 ether}();
    }
    function testFuzz_property(uint256 amount, address actor, bytes32 hash) public {
        // Bound amount to be at least 1 ether (minimum required by lockInGuess)
        amount = bound(amount, 1 ether, type(uint256).max);
        // Avoid precompile addresses and the zero address
        vm.assume(actor != address(0) && actor.code.length == 0);
        vm.assume(actor != address(c));
        // Fund the actor
        vm.deal(actor, amount);

        // Call lockInGuess via try/catch to observe revert behavior
        bool ok;
        vm.startPrank(actor);
        try c.lockInGuess{value: amount}(hash) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // The rule: if lockInGuess did NOT revert, the stored block number for the actor must become non-zero.
        // The buggy version returns early, so it does not revert but leaves the block as zero.
        // Using the public getter for the mapping (guesses(address).block) returns a uint from the Guess struct.
        if (ok) {
            (uint storedBlock, ) = c.guesses(actor);
            assertTrue(storedBlock != 0);
        } else {
            // If it reverted, the property is vacuously true; we assert that the stored block remains 0.
            (uint storedBlock, ) = c.guesses(actor);
            assertTrue(storedBlock == 0);
        }
    }
}

