    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 hash, uint256 fundAmount) public {
        address actor = address(0x1234);
        vm.assume(fundAmount >= 1 ether && fundAmount <= 100 ether);
        vm.deal(actor, fundAmount);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(hash);
