pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 fuzzedActorSeed, bytes32 hash) public {
        address actor = address(uint160(fuzzedActorSeed));
        vm.assume(actor != address(0) && actor != address(c));
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(hash);
        (bool ok, bytes memory data) = address(c).call(abi.encodeWithSignature("settle()"));
        // The reference contract would allow settlement; the buggy one would revert.
        // But we assert on the block field directly via a low-level read using a getter-like pattern.
        // Since guesses is mapping(address => Guess) and Guess is a struct, there is no public getter for the whole struct.
        // We use assembly to read the storage slot for the block field.
        uint256 slot = uint256(keccak256(abi.encode(actor, uint256(1)))); // slot for guesses[actor].block
        uint256 blockValue = uint256(vm.load(address(c), bytes32(slot)));
        assertTrue(blockValue != 0);
    }
}

