pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guessHash, uint256 callerKey) public {
        address caller = vm.addr(callerKey);
        vm.assume(caller != address(0));

        // fund the contract so it can obtain 1 ether from the caller
        vm.deal(address(c), 0);
        // give the caller enough ether for lockInGuess
        vm.deal(caller, 1 ether);

        vm.prank(caller);
        c.lockInGuess{value: 1 ether}(guessHash);

        // Now try to settle.  Advance block number beyond the lock.
        vm.roll(block.number + 2);

        bool ok;
        vm.prank(caller);
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }

        // After a successful lockInGuess, settle must succeed (not revert).
        // The invariant: if lockInGuess did not revert, then the caller's block is non-zero and settle is possible after enough blocks.
        // The mutant leaves guesses[caller].block == 0, causing settle to always revert for any caller/guessHash.
        assertTrue(ok);
    }
}

