pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 hash) public {
        // Restrict domain: the caller must be a valid address that exercises lockInGuess correctly
        address caller = address(0x1234);
        vm.assume(caller != address(0));
        vm.deal(caller, 1 ether);
        vm.prank(caller);
        c.lockInGuess{value: 1 ether}(hash);

        // Advance blocks so settle() can be called
        vm.roll(block.number + 2);

        // Capture balance before settle
        uint256 balanceBefore = caller.balance;

        // Call settle
        vm.prank(caller);
        c.settle();

        uint256 balanceAfter = caller.balance;

        // Assert: if the stored guess equals the correct blockhash answer, balance must increase by 2 ether;
        // otherwise, it must stay the same. The buggy version always stores bytes32(0), so balance never increases.
        bytes32 answer = keccak256(abi.encodePacked(blockhash(block.number - 1)));
        if (hash == answer) {
            assertEq(balanceAfter - balanceBefore, 2 ether);
        } else {
            assertEq(balanceAfter, balanceBefore);
        }
    }
}

