pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        // Provide 1 ether to constructor
        vm.deal(address(this), 1 ether);
        c = new C{value: 1 ether}();
    }

    function testFuzz_property(bytes32 hash) public {
        // Admissible: non-zero hash so the reference lockInGuess stores the real hash.
        // The fuzzer will find a non-zero hash that makes the answer match.
        vm.assume(hash != bytes32(0));

        // Setup actor with enough ether for lockInGuess and a predictable block.
        address actor = address(0xABCD);
        vm.deal(actor, 2 ether);

        // lockInGuess at current block.
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(hash);

        // Advance exactly one block so that the recorded block (block.number at call time)
        // has a blockhash and settle becomes callable.
        uint256 targetBlock = block.number;
        vm.roll(block.number + 1);

        // The guess stored in P equals the original hash.
        // In the buggy version it is always bytes32(0).
        // Compute the answer that would match the stored guess from blockhash.
        bytes32 answer = keccak256(abi.encodePacked(blockhash(targetBlock)));

        // Call settle as actor.
        vm.prank(actor);
        c.settle();

        // After settle, if the answer matches the stored guess (which it does in P because
        // hash == answer is satisfied by fuzzer choosing hash equal to answer),
        // the actor receives 2 ether and their balance becomes 1 ether (after spending 1).
        // In the buggy version, stored guess is bytes32(0) which never equals answer,
        // so no transfer occurs and balance stays at 0 ether (spent 1, received nothing).
        assertTrue(address(actor).balance >= 1 ether);
    }
}
